// Recipe / Meal Planner — recipe library, a 7-day x 3-meal planning grid, and
// a shopping list auto-generated by aggregating ingredients across the
// currently planned week (same-name + same-unit ingredients are summed).

    function getRecipes() { return safeStorage('recipes', []); }
    function getMealPlan() { return safeStorage('mealPlan', {}); }
    function getShoppingList() { return safeStorage('shoppingList', []); }

    let recipeIngredientDraft = [];

    function addRecipeIngredientRow() {
        const name = document.getElementById('recipeIngNameInput').value.trim();
        const qty = safeNum(document.getElementById('recipeIngQtyInput').value);
        const unit = document.getElementById('recipeIngUnitInput').value.trim();
        if (!name || !qty) return showToast('Enter ingredient name & quantity', 'error');
        recipeIngredientDraft.push({ name, qty, unit });
        document.getElementById('recipeIngNameInput').value = '';
        document.getElementById('recipeIngQtyInput').value = '';
        renderRecipeIngredientDraft();
    }

    function renderRecipeIngredientDraft() {
        const c = document.getElementById('recipeIngredientDraftList');
        if (!c) return;
        c.innerHTML = recipeIngredientDraft.map((ing, i) => `
            <div style="display:flex; justify-content:space-between; font-size:12px; padding:3px 0;">
                <span>${sanitizeHTML(ing.name)} — ${ing.qty}${sanitizeHTML(ing.unit || '')}</span>
                <span onclick="recipeIngredientDraft.splice(${i},1); renderRecipeIngredientDraft();" role="button" tabindex="0" style="color:#ff3b30; cursor:pointer;">✖</span>
            </div>
        `).join('');
    }

    function saveRecipe() {
        if (!checkFreeTierLimit('recipes')) return;
        const name = document.getElementById('recipeNameInput').value.trim();
        const notes = document.getElementById('recipeNotesInput').value.trim();
        if (!name) return showToast('Enter a recipe name!', 'error');
        if (!recipeIngredientDraft.length) return showToast('Add at least one ingredient!', 'error');
        const recipes = getRecipes();
        recipes.push({ id: Date.now(), name, ingredients: recipeIngredientDraft.slice(), notes });
        localStorage.setItem('recipes', JSON.stringify(recipes));
        syncToCloud();
        recipeIngredientDraft = [];
        document.getElementById('recipeNameInput').value = '';
        document.getElementById('recipeNotesInput').value = '';
        renderRecipeIngredientDraft();
        renderRecipeLibrary();
        showToast('Recipe saved! 🍲', 'success');
    }

    function deleteRecipe(id) {
        localStorage.setItem('recipes', JSON.stringify(getRecipes().filter(r => r.id !== id)));
        // Also clear it from any meal-plan slots that referenced it
        const plan = getMealPlan();
        Object.keys(plan).forEach(date => ['breakfast', 'lunch', 'dinner'].forEach(slot => {
            if (plan[date] && plan[date][slot] === id) plan[date][slot] = null;
        }));
        localStorage.setItem('mealPlan', JSON.stringify(plan));
        syncToCloud();
        renderRecipeLibrary();
        renderMealPlanWeek();
    }

    function renderRecipeLibrary() {
        const c = document.getElementById('recipeLibraryList');
        if (!c) return;
        const recipes = getRecipes();
        c.innerHTML = recipes.map(r => `
            <div style="background:var(--card-bg,#f7f7f9); border-radius:12px; padding:10px 12px; margin-bottom:8px;">
                <div style="display:flex; justify-content:space-between;"><b style="font-size:13px;">${sanitizeHTML(r.name)}</b>
                <span onclick="deleteRecipe(${r.id})" role="button" tabindex="0" style="color:#ff3b30; cursor:pointer;">✖</span></div>
                <div style="font-size:11px; color:#8e8e93; margin-top:3px;">${r.ingredients.map(i => sanitizeHTML(i.name)).join(', ')}</div>
            </div>
        `).join('') || '<p style="text-align:center; font-size:12px; color:#8e8e93; padding:12px 0;">No recipes yet.</p>';
    }

    function getMealWeekDates() {
        const days = [];
        const start = new Date();
        start.setDate(start.getDate() - start.getDay()); // Sunday of this week
        for (let i = 0; i < 7; i++) {
            const d = new Date(start); d.setDate(d.getDate() + i);
            days.push(d.toISOString().split('T')[0]);
        }
        return days;
    }

    function setMealSlot(date, slot, recipeId) {
        const plan = getMealPlan();
        if (!plan[date]) plan[date] = {};
        plan[date][slot] = recipeId ? Number(recipeId) : null;
        localStorage.setItem('mealPlan', JSON.stringify(plan));
        syncToCloud();
    }

    function renderMealPlanWeek() {
        const c = document.getElementById('mealPlanGrid');
        if (!c) return;
        const recipes = getRecipes();
        const plan = getMealPlan();
        const days = getMealWeekDates();
        const dayLabel = d => new Date(d + 'T00:00').toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric' });
        const optionsFor = selectedId => `<option value="">—</option>` + recipes.map(r =>
            `<option value="${r.id}" ${selectedId === r.id ? 'selected' : ''}>${sanitizeHTML(r.name)}</option>`
        ).join('');
        c.innerHTML = days.map(d => `
            <div style="background:var(--card-bg,#f7f7f9); border-radius:12px; padding:10px; margin-bottom:8px;">
                <b style="font-size:12px;">${dayLabel(d)}</b>
                ${['breakfast', 'lunch', 'dinner'].map(slot => {
                    const selectedId = plan[d] && plan[d][slot] ? plan[d][slot] : null;
                    return `
                    <div style="display:flex; align-items:center; gap:6px; margin-top:6px;">
                        <span style="font-size:11px; color:#8e8e93; width:60px; text-transform:capitalize;">${slot}</span>
                        <select onchange="setMealSlot('${d}','${slot}', this.value)" style="flex:1; font-size:12px;">
                            ${optionsFor(selectedId)}
                        </select>
                    </div>`;
                }).join('')}
            </div>
        `).join('');
    }

    function generateShoppingListFromPlan() {
        const recipes = getRecipes();
        const plan = getMealPlan();
        const days = getMealWeekDates();
        const agg = {}; // key: name|unit -> qty
        days.forEach(d => {
            const slots = plan[d];
            if (!slots) return;
            ['breakfast', 'lunch', 'dinner'].forEach(slot => {
                const recipeId = slots[slot];
                if (!recipeId) return;
                const recipe = recipes.find(r => r.id === recipeId);
                if (!recipe) return;
                recipe.ingredients.forEach(ing => {
                    const key = ing.name.toLowerCase() + '|' + (ing.unit || '');
                    agg[key] = (agg[key] || 0) + Number(ing.qty);
                });
            });
        });
        const list = getShoppingList();
        const existingNames = new Set(list.map(i => i.name.toLowerCase() + '|' + (i.unit || '')));
        let added = 0;
        Object.keys(agg).forEach(key => {
            if (existingNames.has(key)) return;
            const [name, unit] = key.split('|');
            list.push({ id: Date.now() + Math.random(), name, qty: Math.round(agg[key] * 100) / 100, unit, checked: false, fromMealPlan: true });
            added++;
        });
        localStorage.setItem('shoppingList', JSON.stringify(list));
        syncToCloud();
        renderShoppingList();
        showToast(added ? `${added} items added to shopping list! 🛒` : 'Shopping list already up to date', added ? 'success' : 'info');
    }

    function toggleShoppingItem(id) {
        const list = getShoppingList();
        const item = list.find(i => i.id === id);
        if (item) item.checked = !item.checked;
        localStorage.setItem('shoppingList', JSON.stringify(list));
        syncToCloud();
        renderShoppingList();
    }

    function addManualShoppingItem() {
        const name = document.getElementById('shoppingItemInput').value.trim();
        if (!name) return;
        const list = getShoppingList();
        list.push({ id: Date.now() + Math.random(), name, qty: '', unit: '', checked: false, fromMealPlan: false });
        localStorage.setItem('shoppingList', JSON.stringify(list));
        syncToCloud();
        document.getElementById('shoppingItemInput').value = '';
        renderShoppingList();
    }

    function clearCheckedShoppingItems() {
        localStorage.setItem('shoppingList', JSON.stringify(getShoppingList().filter(i => !i.checked)));
        syncToCloud();
        renderShoppingList();
    }

    function renderShoppingList() {
        const c = document.getElementById('shoppingListContainer');
        if (!c) return;
        const list = getShoppingList();
        c.innerHTML = list.map(i => `
            <div style="display:flex; align-items:center; gap:8px; padding:5px 0; ${i.checked ? 'opacity:0.5; text-decoration:line-through;' : ''}">
                <input type="checkbox" ${i.checked ? 'checked' : ''} onchange="toggleShoppingItem(${i.id})">
                <span style="flex:1; font-size:13px;">${sanitizeHTML(i.name)}${i.qty ? ` — ${i.qty}${sanitizeHTML(i.unit || '')}` : ''}</span>
            </div>
        `).join('') || '<p style="text-align:center; font-size:12px; color:#8e8e93; padding:12px 0;">List is empty.</p>';
    }

    function openRecipePlannerModal() {
        renderRecipeLibrary();
        renderMealPlanWeek();
        renderShoppingList();
        openModal('recipePlannerModal');
    }
